-- Warrior RP original speech and emote catalog (frFR)
local _, addon = ...
addon.localeData.frFR.texts = {
    HEROIC_STRIKE = { name = "Frappe héroïque", ziel = { "%s, regardez-moi en face : Ce coup porte plus de détermination que de colère.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Ce coup porte plus de détermination que de colère.", "La frappe porte quand la posture rejoint la volonté.", "*ramène le bras et lance son arme avec toute sa force.*" } },
    CHARGE = { name = "Charge", ziel = { "%s, regardez-moi en face : Il ne reste entre nous que la distance d'un souffle.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Il ne reste entre nous que la distance d'un souffle.", "*porte son poids en avant et s'élance sans hésiter.*", "Hésiter, c'est céder le terrain à l'adversaire.", "*repère la brèche entre deux mouvements précipités.*", "Le plus court chemin vers l'ennemi traverse la peur.", "*prend appui et réduit la distance au pas de course.*" } },
    REND = { name = "Pourfendre", ziel = { "%s, regardez-moi en face : Une garde ouverte se paie bien après l'instant du coup.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Une garde ouverte se paie bien après l'instant du coup.", "Une petite blessure suffit à ruiner de grands projets.", "*fait glisser sa lame à travers la garde d'un geste bref et tranchant.*" } },
    HAMSTRING = { name = "Brise-genou", ziel = { "%s, regardez-moi en face : Inutile de se hâter lorsque l'adversaire ne le peut plus.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Inutile de se hâter lorsque l'adversaire ne le peut plus.", "Un combat devient plus simple quand les jambes de l'ennemi ralentissent.", "*porte une taille basse et mesurée sous la garde.*" } },
    THUNDER_CLAP = { name = "Coup de tonnerre", ziel = {  }, gruppe = { "Le sol lui-même répond à mon pas.", "Vous entendez ce grondement ? Ce n'est que le début.", "*frappe le sol du pied et fait vibrer le terrain alentour.*" } },
    CLEAVE = { name = "Enchaînement", ziel = {  }, gruppe = { "Un seul geste ouvre plusieurs chemins à la lame.", "Deux adversaires, un seul mouvement. Tout est dans les appuis.", "*fait décrire à son arme un arc large et horizontal.*" } },
    EXECUTE = { name = "Exécution", ziel = { "%s, regardez-moi en face : À présent, c'est le moment choisi, pas la fureur, qui décide.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "À présent, c'est le moment choisi, pas la fureur, qui décide.", "Le dernier coup exige la main la plus sûre.", "*attend une infime ouverture et porte le coup décisif.*" } },
    SUNDER_ARMOR = { name = "Fracasser armure", ziel = { "%s, regardez-moi en face : Toute armure possède un point faible.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Toute armure possède un point faible.", "Aucune armure ne tient toujours quand on connaît ses jointures.", "*frappe plusieurs fois les points faibles de l'armure.*" } },
    SHIELD_BLOCK = { name = "Maîtrise du blocage", ziel = {  }, gruppe = { "Mon bouclier attend là où le prochain coup veut tomber.", "L'adversaire peut lever son arme. Mon bouclier l'attend déjà.", "*intercepte le coup sur le bord de son bouclier.*" } },
    SHIELD_BASH = { name = "Coup de bouclier", ziel = { "%s, regardez-moi en face : Nul besoin de lame pour faire taire un sort.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Nul besoin de lame pour faire taire un sort.", "Une incantation interrompue est étonnamment brève.", "*projette son bouclier en avant et brise la concentration adverse.*" } },
    TAUNT = { name = "Provocation", ziel = { "%s, regardez-moi en face : Regardez-moi. Les autres ne sont pas votre problème.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Regardez-moi. Les autres ne sont pas votre problème.", "Je suis là. Pensez-vous vraiment pouvoir passer ?", "*frappe le bord de son bouclier et défie son adversaire.*" } },
    BATTLE_SHOUT = { name = "Cri de guerre", ziel = {  }, gruppe = { "Tenez la ligne ! Pas un pas en arrière.", "Haut les têtes ! Le courage porte plus loin que les étendards.", "*lève son arme et rallie ses compagnons.*" } },
    DEMORALIZING_SHOUT = { name = "Cri démoralisant", ziel = {  }, gruppe = { "Écoutez bien : votre assurance s'arrête ici.", "Vos rangs chancellent avant même mon arrivée.", "*lance un cri de guerre profond et tranchant.*" } },
    REVENGE = { name = "Vengeance", ziel = { "%s, regardez-moi en face : Qui éprouve mon bouclier reçoit aussitôt sa réponse.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Qui éprouve mon bouclier reçoit aussitôt sa réponse.", "Votre dernier coup m'a offert une occasion.", "*dévie l'arme adverse et riposte aussitôt.*" } },
    OVERPOWER = { name = "Fulgurance", ziel = { "%s, regardez-moi en face : Une faille dans la garde est une invitation.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Une faille dans la garde est une invitation.", "Un pas de trop. L'ouverture m'appartient.", "*profite d'une garde déséquilibrée pour riposter vivement.*" } },
    MORTAL_STRIKE = { name = "Frappe mortelle", ziel = { "%s, regardez-moi en face : Je mise tout sur un coup lourd et précis.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Je mise tout sur un coup lourd et précis.", "Ce coup n'est pas un hasard, mais l'aboutissement d'une décision.", "*guide son arme lourde avec une précision implacable.*" } },
    WHIRLWIND = { name = "Tourbillon", ziel = {  }, gruppe = { "L'acier et le mouvement forment un cercle sans faille.", "Un cercle d'acier laisse peu de place aux bravades.", "*pivote sur un pied et fait tournoyer son arme.*" } },
    BLOODTHIRST = { name = "Sanguinaire", ziel = { "%s, regardez-moi en face : Je maintiens la pression jusqu'à céder la garde.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Je maintiens la pression jusqu'à céder la garde.", "Ma fureur s'éveille, mais ma lame reste précise.", "*poursuit l'assaut d'un coup féroce sans baisser sa garde.*" } },
    INTERCEPT = { name = "Interception", ziel = { "%s, regardez-moi en face : Aucune distance n'est sûre tant que je peux tenir debout.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Aucune distance n'est sûre tant que je peux tenir debout.", "*porte son poids en avant et s'élance sans hésiter.*", "Hésiter, c'est céder le terrain à l'adversaire.", "*repère la brèche entre deux mouvements précipités.*", "Un pas de fuite ne crée aucune distance sûre.", "*jaillit de sa garde et coupe la route de fuite.*" } },
    PUMMEL = { name = "Volée de coups", ziel = { "%s, regardez-moi en face : La prochaine syllabe de votre sort restera muette.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "La prochaine syllabe de votre sort restera muette.", "Un coup de poing vif répond parfois mieux à la magie.", "*frappe au bon moment et interrompt l'incantation.*" } },
    SWEEPING_STRIKES = { name = "Attaques circulaires", ziel = {  }, gruppe = { "Chaque rotation de l'arme a sa raison d'être.", "Aucun coup ne doit s'arrêter à la première garde.", "*prolonge l'élan de son arme jusqu'à un second coup.*" } },
    DEATH_WISH = { name = "Souhait mortel", ziel = {  }, gruppe = { "Je connais le risque. J'avance malgré tout.", "Je vois le danger nettement. Il ne me fera pas reculer.", "*relâche son bras de bouclier et avance son arme avec résolution.*" } },
    RECKLESSNESS = { name = "Témérité", ziel = {  }, gruppe = { "En cet instant, seule compte l'attaque résolue.", "Quand la décision est prise, il faut saisir l'instant entier.", "*abandonne toute retenue dans une suite de coups implacables.*" } },
    LAST_STAND = { name = "Dernier rempart", ziel = {  }, gruppe = { "Tant que je respire, cette ligne tiendra.", "Voici ma position. Je resterai ici.", "*se redresse encore malgré le poids de la fatigue.*" } },
    SHIELD_WALL = { name = "Mur protecteur", ziel = {  }, gruppe = { "Derrière ce bouclier, il n'y aura pas de retraite.", "Un bouclier est utile. Une ligne intacte vaut mieux.", "*ramène son bouclier et verrouille sa garde.*" } },
    RETALIATION = { name = "Représailles", ziel = {  }, gruppe = { "Chaque coup retrouvera son chemin.", "Chaque attaque ouvre aussi une riposte.", "*absorbe le mouvement et frappe aussitôt dans l'ouverture.*" } },
    MOCKING_BLOW = { name = "Coup railleur", ziel = { "%s, regardez-moi en face : Approchez. Je suis loin d'en avoir fini.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Approchez. Je suis loin d'en avoir fini.", "Un peu d'orgueil vous rend prévisible.", "*simule un coup maladroit pour attirer l'adversaire.*" } },
    BERSERKER_RAGE = { name = "Rage berserker", ziel = {  }, gruppe = { "La peur n'a plus sa place ici.", "La peur attendra. C'est la volonté qui parle.", "*chasse la peur d'une expiration rauque.*" } },
    BLOODRAGE = { name = "Rage sanguinaire", ziel = {  }, gruppe = { "Je puise ma force dans chaque battement précipité.", "Ma douleur ne brisera pas ma force.", "*frappe son poing contre sa poitrine et réveille son ardeur.*" } },
    DISARM = { name = "Désarmement", ziel = { "%s, regardez-moi en face : Une arme ne vaut rien lorsqu'elle quitte la main.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Une arme ne vaut rien lorsqu'elle quitte la main.", "Une main vide répond clairement à la vantardise.", "*fait levier sur le bras armé de l'ennemi.*" } },
    INTIMIDATING_SHOUT = { name = "Cri d'intimidation", ziel = {  }, gruppe = { "Qui perd son courage perd aussi sa formation.", "Fuyez tant que vos jambes vous portent !", "*pousse un cri si puissant qu'il domine le tumulte du combat.*" } },
    CHALLENGING_SHOUT = { name = "Cri de défi", ziel = {  }, gruppe = { "Tous les regards sur moi. Tout se joue ici.", "Vous tous ! Voici l'adversaire que vous cherchiez.", "*lève son bouclier au-dessus de sa tête et défie tous les assaillants.*" } },
    SLAM = { name = "Heurtoir", ziel = { "%s, regardez-moi en face : Un coup net exige du poids et de la patience.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Un coup net exige du poids et de la patience.", "La lame ne tombe pas seulement avec force. Elle tombe juste.", "*arme son bras et abat son arme de tout son poids.*" } },
    DEVASTATE = { name = "Dévaster", ziel = { "%s, regardez-moi en face : Je trouve le point faible et ne lui laisse aucun appui.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Je trouve le point faible et ne lui laisse aucun appui.", "Une armure faible cède; une armure brisée cède plus vite.", "*frappe une section déjà abîmée de l'armure adverse.*" } },
    SHIELD_SLAM = { name = "Heurt de bouclier", ziel = { "%s, regardez-moi en face : Mon bouclier répond aussi vite que mon arme.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Mon bouclier répond aussi vite que mon arme.", "Mon bouclier n'est pas une décoration au bras gauche.", "*projette le bord de son bouclier de toute sa force.*" } },
    CONCUSSION_BLOW = { name = "Bourrasque", ziel = { "%s, regardez-moi en face : Un instant d'inattention peut ruiner tout un plan.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Un instant d'inattention peut ruiner tout un plan.", "Un coup net peut voler une pensée entière à l'ennemi.", "*porte un coup lourd dans une garde ouverte.*" } },
    VICTORY_RUSH = { name = "Ivresse de la victoire", ziel = { "%s, regardez-moi en face : Le prochain pas appartient aux survivants.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "Le prochain pas appartient aux survivants.", "Une victoire donne la force du pas suivant.", "*se redresse après la victoire et avance aussitôt.*" } },
    BATTLE_STANCE = { name = "Posture de combat", ziel = {  }, gruppe = { "*déplace son poids et adopte une posture de combat équilibrée.*", "De bons appuis préparent chaque mouvement.", "*évalue la distance et tient son arme prête.*", "Un guerrier garde son équilibre quand le combat commence.", "Je tiens le centre et garde toutes les voies ouvertes.", "*prend une posture équilibrée, prêt à attaquer ou riposter.*" } },
    DEFENSIVE_STANCE = { name = "Posture défensive", ziel = {  }, gruppe = { "*ramène son bouclier contre le corps et ferme sa garde.*", "Derrière mon bouclier, notre ligne tiendra.", "*plante ses pieds dans le sol et attend le premier coup.*", "Pour atteindre mes alliés, il faudra d'abord me dépasser.", "Aujourd'hui, le bouclier compte plus que la gloire.", "*abaisse son centre de gravité et protège ses alliés du bouclier.*" } },
    BERSERKER_STANCE = { name = "Posture berserker", ziel = {  }, gruppe = { "*s'abaisse sur ses appuis et pousse un cri de guerre rauque.*", "Ma fureur connaît sa cible; mon esprit reste lucide.", "*fait tournoyer son arme dans un geste résolu.*", "À présent, il n'est plus question de reculer.", "La fureur a ouvert sa porte. Ma main la guidera.", "*adopte une posture agressive et avance son arme.*" } },
    PIERCING_HOWL = { name = "Hurlement perçant", ziel = {  }, gruppe = { "*lance un hurlement perçant à travers le champ de bataille.*", "Vous ne vous échapperez pas si facilement !", "*pousse un cri qui domine le fracas de l'acier et des tambours.*", "Restez là et affrontez-moi !", "Même derrière les rangs, on entendra mon appel.", "*inspire profondément et pousse un long hurlement perçant.*" } },
    SPEARING_STRIKE = { name = "Coup empalant", ziel = { "%s, même un géant doit se garder d'une pointe bien dirigée.", "*se tourne vers %s et entame une attaque précise.*" }, gruppe = { "*se lance dans une estocade droite et puissante.*", "La taille ne protège pas d'une pointe bien placée.", "*prend sa mesure et concentre sa force dans une estocade.*", "Une estocade nette demande de la résolution, pas de la hâte.", "La pointe trouve son chemin là où l'armure cède.", "*concentre tout son élan dans une estocade droite.*" } },
    TACTICAL_MASTERY = { name = "Maîtrise tactique", ziel = {  }, gruppe = { "*change de posture sans perdre le rythme du combat.*", "Une nouvelle posture, la même volonté de fer.", "*ajuste ses appuis et conserve son élan guerrier.*", "Un guerrier avisé ne gaspille ni ses pas ni ses forces.", "Un pas de côté vaut parfois mieux que dix coups désordonnés.", "*change ses appuis sans perdre de vue les adversaires.*" } },
}
